// R4.7, review fix iteration 2: the third corpus pair (fresh-*, ported from the security reviewer's
// iteration 2 harnesses and generalised by family) and one test per finding. Generated by
// gen-fresh.mjs. Timing lives in redaction-timing.test.ts.
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { compileRedactionConfig } from "../../src/redaction/config.ts";
import { createRedactor, redactorFromConfig } from "../../src/redaction/redactor.ts";

const here = dirname(fileURLToPath(import.meta.url));
const gen = join(here, ".generated");
const read = (f: string): string => readFileSync(join(gen, f), "utf8");
const red = createRedactor();
const leaks = (out: string, s: string): boolean =>
  out.includes(s) || out.includes(JSON.stringify(s).slice(1, -1));
const wrap = (content: string): string =>
  JSON.stringify({ type: "user", message: { content: [{ type: "tool_result", content }] } });
const text = (out: string): string =>
  (JSON.parse(out) as { message: { content: { content: string }[] } }).message.content[0]!.content;

const secretLines = read("fresh-secret-corpus.jsonl").split("\n").filter(Boolean);
const expected = JSON.parse(read("fresh-secret-corpus.expected.json")) as {
  label: string;
  secrets: string[];
}[];
const benign = read("fresh-benign-corpus.txt")
  .split("\n")
  .filter(Boolean)
  .map((l) => JSON.parse(l) as string);

describe("fresh corpora (security review, iteration 2)", () => {
  it("secret corpus: 0 leaks, JSON stays valid", () => {
    expect(secretLines).toHaveLength(expected.length);
    const bad: string[] = [];
    let n = 0;
    secretLines.forEach((line, i) => {
      const out = red.redactLine(line);
      for (const s of expected[i]!.secrets) {
        n += 1;
        if (leaks(out, s)) bad.push(`${expected[i]!.label} :: ${line.slice(0, 100)}`);
      }
      if (line.startsWith("{")) expect(() => JSON.parse(out), expected[i]!.label).not.toThrow();
    });
    console.log(
      `fresh secret corpus: leaks: ${bad.length}/${n} secrets, ${secretLines.length} lines`,
    );
    expect(bad).toEqual([]);
  });

  it("benign corpus: under 2% of lines change", () => {
    const changed = benign.filter((t) => red.redactLine(wrap(t)) !== wrap(t));
    const pct = (changed.length / benign.length) * 100;
    console.log(
      `fresh benign corpus: false positives: ${changed.length}/${benign.length} = ${pct.toFixed(1)}%`,
    );
    if (changed.length > 0) console.log(changed.map((l) => `  FP: ${l}`).join("\n"));
    expect(pct).toBeLessThan(2);
  });
});

describe("iteration 2 findings", () => {
  const sec = (t: string, secret: string): void => {
    const out = red.redactLine(wrap(t));
    expect(out, t).not.toContain(secret);
    expect(out, t).toContain("[redacted:");
  };
  const same = (t: string): void => expect(red.redactLine(wrap(t)), t).toBe(wrap(t));

  it("HIGH 1: separators => := ?= ||=, key closers, XML element, attribute pair, k8s env pair", () => {
    const v = "Hk29dLq7VzQ";
    sec(`"password" => "${v}"`, v);
    sec(`password := "${v}"`, v);
    sec(`API_KEY ?= ${v}`, v);
    sec(`os.environ["API_KEY"] = "${v}"`, v);
    sec(`$c['smtp_password']='${v}';`, v);
    sec(`<password>${v}</password>`, v);
    sec(`<server>\n  <password>\n    ${v}\n  </password>\n</server>`, v);
    sec(`<add key="ClearTextPassword" value="${v}" />`, v);
    sec(`<add key='ApiKey' value='${v}'/>`, v);
    sec(`{"name":"DB_PASSWORD","value":"${v}"}`, v);
    sec(`- name: API_TOKEN\n  value: "${v}"`, v);
    sec(`define('DB_PASSWORD', '${v}');`, v);
    same('<add key="Timeout" value="30"/>');
    same("<password>${env.DB_PASSWORD}</password>");
  });

  it("HIGH 2: a base64 PEM private key is redacted; a base64 certificate is not", () => {
    const key = "LS0tLS1CRUdJTiBSU0EgUFJJVkFURSBLRVktLS0tLQpNSUlFb3dJQkFBS0NBUUVB";
    sec(`    client-key-data: ${key}`, key);
    sec(`data: ${key}`, key);
    const cert = Buffer.from("-----BEGIN CERTIFICATE-----\n" + "MIIC".repeat(20)).toString(
      "base64",
    );
    expect(red.redactLine(wrap(`x ${cert}`))).toBe(wrap(`x ${cert}`));
    sec(JSON.stringify({ "client-key-data": "AAAAAAAAAAAAAAAA" }), "AAAAAAAAAAAAAAAA");
  });

  it("HIGH 3: PowerShell secure strings and single-dash parameters", () => {
    const v = "Zq8#vL!2m@Xp$4";
    sec(`ConvertTo-SecureString "${v}" -AsPlainText -Force`, v);
    sec(`ConvertTo-SecureString -String '${v}' -AsPlainText`, v);
    sec(`ConvertTo-SecureString -AsPlainText -Force -String "${v}"`, v);
    sec(`Some-Cmdlet -Password ${v}`, v);
    sec(`Some-Cmdlet -ApiKey:${v}`, v);
    sec(`Some-Cmdlet -Token "${v} x y"`, "x y");
    same("Invoke-Foo -Password $cred.Password");
    same("$s = Read-Host -AsSecureString");
    same("Invoke-Foo -Password (Read-Host)");
  });

  it("MEDIUM 4: pass, .netrc, quoted CLI values to the matching quote, -p'secret'", () => {
    sec("pass: Hk29dLq7VzQ", "Hk29dLq7VzQ");
    sec('{"pass":"Hk29dLq7VzQ"}', "Hk29dLq7VzQ");
    sec("machine h login u password Hk29dLq7VzQ", "Hk29dLq7VzQ");
    sec("machine h\n  login u\n  password Hk29dLq7VzQ", "Hk29dLq7VzQ");
    same("bypass: enabled");
    same("PASS: relaunch and re-check");
    for (const [t, rest] of [
      ['--password="Hk29 dLq7"', "dLq7"],
      ['mysql --password "P@ss w0rd!"', "w0rd"],
      ['--password="Tr0ub4dor&3x"', "3x"],
      ['sshpass -p "Tr0ub4dor;3x"', "3x"],
      ['mysql --password "correct horse battery"', "horse"],
      ['setx DB_PASSWORD "ab cd ef gh"', "cd ef"],
      ['docker login -p "x yz12345"', "yz12345"],
      ["mysql -uroot -p'Hk29 dLq7VzQ'", "dLq7VzQ"],
      ["app --password letmein", "letmein"],
    ] as const) {
      const out = text(red.redactLine(wrap(t)));
      expect(out, t).toContain("[redacted:");
      expect(out, t).not.toContain(rest);
    }
    same("use --token with a GitHub PAT");
    same("see --password option in man page");
    same('docker run -p"8080:80" x');
  });

  it("MEDIUM 5: Vault, Stripe webhook, SAS, Heroku, Teams and a dozen more token formats", () => {
    for (const t of [
      "hvs." + "CAESIAbCdEf0123456789AbCdEf",
      "whsec_AbCdEf0123456789AbCdEf",
      "https://a.blob.core.windows.net/c/b?sv=2021&sig=AbCdEf0123456789%2FAbCd%3D&se=2026",
      "HRKU-AbCdEf01-2345-6789-AbCd-Ef0123456789",
      "https://x.office.com/webhook/a@b/IncomingWebhook/0123456789abcdef0123456789abcdef/c1d2e3f4",
      "dop_v1_" + "ab12".repeat(16),
      "shpat_0123456789abc" + "def0123456789abcdef",
      "GOCSPX-AbCdEf0123456789AbCdEf012",
      "ya29.a0AbCdEf0123456789AbCdEf012345",
      "1234567890:AAEhBP0av18F1Z2Xw3Y4V5u6T7s8R9q0P1o",
      "pypi-AgEIcHlwaS5vcmc" + "A".repeat(60),
      "xapp-" + "1-A0123456789-" + "0123456789-abcdef",
    ]) {
      const out = red.redactLine(wrap(`x ${t} y`));
      expect(out, t).toContain("[redacted:");
      expect(out, t).not.toContain(t.slice(-16));
    }
  });

  it("MEDIUM 6: the deny validator rejects exact-count nesting and a second unbounded quantifier", () => {
    for (const p of [
      "(?:\\w+){4}!x",
      "(\\w+){4}",
      ".*.*.*z",
      "\\w+@\\w+\\.com",
      "((a+))+b",
      "(a{1,99}){1,99}b",
      "a?a?a?a?a?a?a?ab",
      "(a|b){9}c",
    ]) {
      expect(compileRedactionConfig({ deny: [{ name: "u", pattern: p }] }).ok, p).toBe(false);
    }
    for (const p of [
      "CORP-[0-9]{8}",
      "(\\d{3}-){3}x",
      "https?://\\S+",
      "\\w{1,64}@\\w{1,64}\\.com",
    ]) {
      expect(compileRedactionConfig({ deny: [{ name: "u", pattern: p }] }).ok, p).toBe(true);
    }
  });

  it("MEDIUM 6: an accepted deny pattern is bounded by the window on adversarial input", () => {
    const r = redactorFromConfig({ deny: [{ name: "d", pattern: ".*z" }] }).redactor;
    const t0 = performance.now();
    r.redactLine(JSON.stringify({ t: "a".repeat(20000) }));
    expect(performance.now() - t0).toBeLessThan(1000);
  });

  it("LOW 7: cookies need a pair; prose and attributes stay", () => {
    sec("Cookie: sid=AbCd1234; csrftoken=Zz99", "AbCd1234");
    sec('document.cookie = "sid=AbCd1234EfGh5678"', "AbCd1234EfGh5678");
    sec("curl -b 'sid=AbCd1234EfGh5678' https://x", "AbCd1234EfGh5678");
    same("// Cookie: name=value pairs are parsed below");
    same("the cookie: it stores x=1 for a week");
    same("Set-Cookie: SameSite=Lax is required");
  });

  it("LOW 8: a rejected bare value gives its span back; --password hunter is caught", () => {
    sec("token=a(b)password=Zq8#vL!2m@Xp$4", "Zq8#vL");
    sec("--password hunter", "hunter");
  });

  it("code review 3: deny patterns run on short strings", () => {
    const r = redactorFromConfig({ deny: [{ name: "pin", pattern: "PIN[0-9]{2}" }] }).redactor;
    expect(r.redactLine('{"a":"PIN12"}')).toBe('{"a":"[redacted:pin]"}');
  });

  it("code review 4: two keys that redact to the same text both survive", () => {
    const line = JSON.stringify({ "password=Hk29dLq7VzQ1": "a", "password=Hk29dLq7VzQ2": "b" });
    const out = red.redactLine(line);
    expect(out).not.toContain("Hk29dLq7VzQ");
    const o = JSON.parse(out) as Record<string, string>;
    expect(Object.values(o).sort()).toEqual(["a", "b"]);
  });
});
